  if (sty==='ghost')     return { g:[234,62,8],  mem:[H,24,96], back:[H,50,40], node:[H,10,100], anno:[H,16,84], ctr:[12,70,58], grain:16, add:true,  wash:[H,44,58], ten:[14,80,100], com:[196,74,100], plot:[H,50,90] };
  if (sty==='fea')       return { g:[228,44,7],  mem:[210,20,72], back:[214,40,30], node:[0,0,96], anno:[52,54,88], ctr:[10,66,64], grain:12, add:false, wash:[210,40,54], ten:[10,86,100], com:[220,82,100], plot:[52,66,92] };
  return { g:[H,17,20], mem:[H,4,94], back:[H,16,44], node:[H,6,88], anno:[H,6,88], ctr:[10,66,62], grain:28, add:false, wash:[H,12,80], ten:[10,74,94], com:[206,68,92], plot:[H+28,58,90] };
}
const C = pal();
const hw = h => ((h%360)+360)%360;
const sc = (c,a) => { stroke(hw(c[0]), c[1], c[2], a*AL); };
const fc = (c,a) => { fill(hw(c[0]), c[1], c[2], a*AL); };
const fea = (sty==='fea');

// ---- clock ------------------------------------------------------------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .08); S.pt = K.t;
const drx = .9*Math.sin(K.t*.137) + .5*Math.sin(K.t*.293+1.7) + .32*Math.sin(K.t*.451);
const dry = .8*Math.sin(K.t*.109+2.1) + .45*Math.sin(K.t*.257+.6) + .28*Math.sin(K.t*.617+1.9);
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.42+.58*NRG)*(.55+.5*K.intensity) + S.bs*.3;

// ---- truss build ------------------------------------------------------------
const nb = Math.round(4 + cl(P.density,0,1)*8);            // bays
const SPAN = u*.74*cl(P.scale,.45,2.0);
const HGT  = SPAN*(.13 + .09*fr(5.1));
const cxs = cl(P.x,.15,.85)*width  + u*.012*NRG*drx;
const cys = cl(P.y,.18,.7)*height + u*.010*NRG*dry;
const typ = Math.floor(fr(2.7)*4) % 4;                      // 0 warren 1 warren+v 2 pratt 3 howe
const TYPN = ['WARREN','WARREN + VERTICALS','PRATT','HOWE'][typ];
const bkey = sd+'|'+nb+'|'+Math.round(SPAN)+'|'+Math.round(cxs)+'|'+Math.round(cys)+'|'+typ;

function mk(px,py,pin){ return { x:px, y:py, rx:px, ry:py, vx:0, vy:0, pin:!!pin, top:false }; }
if (S.bk !== bkey){
  S.bk = bkey;
  S.pl = [];
  for (let pl=0; pl<2; pl++){
    const N = [], M = [];
    const bay = SPAN/nb, x0 = cxs - SPAN/2;
    const bot = [], top = [];
    for (let i=0;i<=nb;i++){ const n = mk(x0+i*bay, cys, i===0 || i===nb); N.push(n); bot.push(N.length-1); }
    if (typ===0){
      for (let i=0;i<nb;i++){ const n = mk(x0+(i+.5)*bay, cys-HGT); n.top=true; N.push(n); top.push(N.length-1); }
      for (let i=0;i<nb;i++){ M.push({a:bot[i],b:top[i],k:2}); M.push({a:top[i],b:bot[i+1],k:2}); }
      for (let i=0;i<top.length-1;i++) M.push({a:top[i],b:top[i+1],k:1});
    } else if (typ===1){
      for (let i=0;i<=nb;i++){ const n = mk(x0+i*bay, cys-HGT); n.top=true; N.push(n); top.push(N.length-1); }
      for (let i=0;i<=nb;i++) M.push({a:bot[i],b:top[i],k:3});
      for (let i=0;i<nb;i++){ M.push({a:bot[i],b:top[i+1],k:2}); M.push({a:top[i],b:bot[i+1],k:2}); }
      for (let i=0;i<nb;i++) M.push({a:top[i],b:top[i+1],k:1});
    } else {
      for (let i=1;i<nb;i++){ const n = mk(x0+i*bay, cys-HGT); n.top=true; N.push(n); top.push(N.length-1); }
      M.push({a:bot[0],b:top[0],k:1}); M.push({a:top[top.length-1],b:bot[nb],k:1});
      for (let i=0;i<top.length-1;i++) M.push({a:top[i],b:top[i+1],k:1});
      for (let i=0;i<top.length;i++) M.push({a:top[i],b:bot[i+1],k:3});
      const mid = nb/2;
      for (let i=0;i<top.length;i++){
        const bi = i+1;
        const toward = (bi < mid) ? (typ===2 ? bi+1 : bi-1) : (typ===2 ? bi-1 : bi+1);
        if (toward>=0 && toward<=nb && toward!==bi) M.push({a:top[i],b:bot[toward],k:2});
      }
    }
    for (let i=0;i<nb;i++) M.push({a:bot[i],b:bot[i+1],k:0});
    for (const m of M){ m.rest = Math.hypot(N[m.b].x-N[m.a].x, N[m.b].y-N[m.a].y); m.f = 0; }
    S.pl.push({ N, M, bot, top });
  }
  S.fmax = 1e-4;
  S.lp = [];
  for (let i=0;i<4;i++) S.lp.push({ p: fr(i*3.3+7)*1.3 - .15, r: .045 + fr(i*5.9+2)*.055 });
}
const planes = S.pl || [];
const nLoad = 2 + Math.round(cl(P.density,0,1)*2);

// ---- rolling loads (real time, incommensurate rates -> never re-phases) ------
for (let i=0;i<S.lp.length;i++){
  const L = S.lp[i];
  L.p += dt * L.r * P.speed * (.6+.8*K.intensity) * (1 + .18*Math.sin(K.t*(.11+i*.037)+i));
  if (L.p > 1.18) L.p -= 1.36;
}

// ---- PBD solve: stable, small strain; the DRAWING exaggerates it -------------
const GR = u*2.6;
const LOADF = u*(9 + 26*NRG);
const hstep = 1/120;
const steps = cl(Math.round(dt/hstep), 1, 3);
const vib = .55*Math.sin(K.t*3.11) + .3*Math.sin(K.t*5.29+1.3) + .18*Math.sin(K.t*8.13+2.6);
for (let pl=0; pl<planes.length; pl++){
  const T = planes[pl], N = T.N, M = T.M;
  const lat = pl===0 ? .62 : .38;
  for (let s=0;s<steps;s++){
    for (let i=0;i<N.length;i++){
      const n = N[i]; if (n.pin){ n.x=n.rx; n.y=n.ry; n.vx=0; n.vy=0; continue; }
      const ox = n.x, oy = n.y;
      n.vy += GR*hstep;
      n.vx += (u*.5)*vib*hstep*(n.top?1:.4)*(.3+.7*NRG);
      if (n.top){
        for (let li=0; li<nLoad; li++){
          const L = S.lp[li]; const lx = cxs - SPAN/2 + L.p*SPAN;
          const w = Math.max(0, 1 - Math.abs(n.rx - lx)/(SPAN/nb));
          n.vy += LOADF * w * lat * hstep;
        }
      }
      n.x += n.vx*hstep; n.y += n.vy*hstep;
      n.ox = ox; n.oy = oy;
    }
    for (let it=0; it<8; it++){
      for (let mi=0; mi<M.length; mi++){
        const m = M[mi], a = N[m.a], b = N[m.b];
        const dx = b.x-a.x, dy = b.y-a.y;
        const L = Math.hypot(dx,dy) || 1e-6;
        const corr = ((L - m.rest)/L) * .5 * .55;
        const wa = a.pin?0:1, wb = b.pin?0:1, wt = wa+wb;
        if (!wt) continue;
        const cx2 = dx*corr*2/wt, cy2 = dy*corr*2/wt;
        if (wa){ a.x += cx2; a.y += cy2; }
        if (wb){ b.x -= cx2; b.y -= cy2; }
      }
    }
    for (let i=0;i<N.length;i++){
      const n = N[i]; if (n.pin) continue;
      n.vx = (n.x - n.ox)/hstep * .992; n.vy = (n.y - n.oy)/hstep * .992;
      // safety: never let the frame run away
      if (Math.abs(n.x-n.rx) > SPAN*.4){ n.x = n.rx + Math.sign(n.x-n.rx)*SPAN*.4; n.vx = 0; }
      if (Math.abs(n.y-n.ry) > SPAN*.4){ n.y = n.ry + Math.sign(n.y-n.ry)*SPAN*.4; n.vy = 0; }
    }
  }
  for (let mi=0; mi<M.length; mi++){
    const m = M[mi], a = N[m.a], b = N[m.b];
    const L = Math.hypot(b.x-a.x, b.y-a.y);
    const st = (L - m.rest)/Math.max(1e-6, m.rest);
    m.f = m.f*.72 + st*.28;
    const af = Math.abs(m.f); if (af > S.fmax) S.fmax = af;
  }
}
S.fmax = Math.max(1e-4, (S.fmax||1e-4)*.994);

// ---- cached plate texture ---------------------------------------------------
const gkey = sd+'|'+sty+'|'+width+'x'+height;
if (!S.gr || S.gkey !== gkey){
  if (S.gr && S.gr.remove) S.gr.remove();
  const gw=170, gh=Math.max(60, Math.round(170*height/Math.max(1,width)));
  const g = createGraphics(gw,gh); g.loadPixels();
  for (let y=0;y<gh;y++) for (let x=0;x<gw;x++){
    const v = cl(255*(.44 + .32*fr(Math.floor(x/8)*13.71+Math.floor(y/8)*7.33+3.1) + .16*fr(Math.floor(x/3)*3.17+Math.floor(y/3)*11.9+8.7) + .08*fr(x*1.13+y*3.31+1.7)),0,255);
    const j=(y*gw+x)*4; g.pixels[j]=v; g.pixels[j+1]=v; g.pixels[j+2]=v; g.pixels[j+3]=255;
  }
  g.updatePixels(); S.gr = g; S.gkey = gkey;
}

// ---- ground -----------------------------------------------------------------
noStroke(); fill(C.g[0],C.g[1],C.g[2],100); rect(0,0,width,height);
push(); blendMode(MULTIPLY); tint(0,0,100,C.grain); image(S.gr,0,0,width,height); pop();
