const wx = width*(.5+.28*Math.sin(K.t*.071)), wy = height*(.42+.22*Math.sin(K.t*.097+1.2));
push(); blendMode(SCREEN); noStroke();
for (let i=5;i>=1;i--){ fill(C.wash[0],C.wash[1],C.wash[2],(2.0+1.8*glow)*AL); const rw=u*(.30+i*.20); ellipse(wx,wy,rw*2,rw*1.6); }
pop(); blendMode(BLEND);
// drafting grid
const gs2 = u*.05;
sc(C.anno, 7 + 6*anno); strokeWeight(Math.max(.5,u*.0008));
for (let x=(-drx*u*.008)%gs2; x<width; x+=gs2) line(x,0,x,height);
for (let y=(-dry*u*.008)%gs2; y<height; y+=gs2) line(0,y,width,y);

// ---- exaggerated deflection mapping (exactly what a real diagram does) -------
const EX = 1.6 + 5.4*NRG;
const DXO = u*.075*DEP, DYO = -u*.052*DEP;
const nx = (n,pl) => n.rx + (n.x-n.rx)*EX + (pl?DXO:0);
const ny = (n,pl) => n.ry + (n.y-n.ry)*EX + (pl?DYO:0);

function forceCol(f){
  const t = cl(f/(S.fmax*1.05), -1, 1);
  const mag = Math.abs(t);
  const c2 = t > 0 ? C.ten : C.com;
  return [c2[0], c2[1]*Math.pow(mag,.62), C.mem[2]*(1-mag*.35) + c2[2]*mag*.35];
}
if (C.add) blendMode(ADD);

// ---- back plane -------------------------------------------------------------
for (let pl=1; pl>=0; pl--){
  const T = planes[pl]; if (!T) continue;
  const N = T.N, M = T.M;
  const dim = pl ? .46 : 1;
  if (pl===1){
    // lacing between the two planes: the space-frame bracing
    const T0 = planes[0];
    sc(C.back, 40*dim + 26*anno); strokeWeight(Math.max(.5,u*.0009));
    for (let i=0;i<T.N.length;i++){
      const nA = T0.N[i], nB = T.N[i]; if (!nA || !nB) continue;
      line(nx(nA,0), ny(nA,0), nx(nB,1), ny(nB,1));
      const nC = T0.N[i+1];
      if (nC && nC.top === nB.top) line(nx(nC,0), ny(nC,0), nx(nB,1), ny(nB,1));
    }
  }
  for (let mi=0; mi<M.length; mi++){
    const m = M[mi], a = N[m.a], b = N[m.b];
    const ax = nx(a,pl), ay = ny(a,pl), bx = nx(b,pl), by = ny(b,pl);
    const fcol = forceCol(m.f);
    const heavy = (m.k===0 || m.k===1);
    const lw = Math.max(.8, u*(heavy? .0042 : .0026) * (.55+.75*NRG)) * dim;
    if (fea){
      sc(fcol, (72+24*glow)*dim); strokeWeight(lw*2.1); line(ax,ay,bx,by);
    } else {
      sc(C.mem, (C.add? 34:70)*dim); strokeWeight(lw*1.9); line(ax,ay,bx,by);
      sc(fcol, (78+20*glow)*dim); strokeWeight(lw*.85); line(ax,ay,bx,by);
    }
  }
  // nodes / gusset plates
  for (let i=0;i<N.length;i++){
    const n = N[i]; const px2 = nx(n,pl), py2 = ny(n,pl);
    const r = Math.max(1.5, u*.0058*cl(P.scale,.5,2)) * dim;
    if (fea){ noStroke(); fc(C.node, 88*dim); ellipse(px2,py2,r*1.3,r*1.3); }
    else {
      noStroke(); fc(C.g, (C.add?24:88)*dim); ellipse(px2,py2,r*2,r*2);
      noFill(); sc(C.node, 90*dim); strokeWeight(Math.max(.5,u*.0012)); ellipse(px2,py2,r*2,r*2);
