    }
  }
  if (pl===0){
    // supports: pin (left) + roller (right)
    const L0 = N[T.bot[0]], R0 = N[T.bot[T.bot.length-1]];
    const r = u*.016*cl(P.scale,.5,1.6);
    noFill(); sc(C.anno, 86); strokeWeight(Math.max(.7,u*.0016));
    triangle(L0.rx, L0.ry, L0.rx-r*.85, L0.ry+r*1.5, L0.rx+r*.85, L0.ry+r*1.5);
    line(L0.rx-r*1.2, L0.ry+r*1.5, L0.rx+r*1.2, L0.ry+r*1.5);
    triangle(R0.rx, R0.ry, R0.rx-r*.85, R0.ry+r*1.15, R0.rx+r*.85, R0.ry+r*1.15);
    ellipse(R0.rx-r*.42, R0.ry+r*1.5, r*.7, r*.7); ellipse(R0.rx+r*.42, R0.ry+r*1.5, r*.7, r*.7);
    line(R0.rx-r*1.2, R0.ry+r*1.85, R0.rx+r*1.2, R0.ry+r*1.85);
    sc(C.ctr, 62); strokeWeight(Math.max(.4,u*.0008));
    for (let i=-3;i<=3;i++){ line(L0.rx+i*r*.4, L0.ry+r*1.5, L0.rx+i*r*.4-r*.34, L0.ry+r*1.95);
      line(R0.rx+i*r*.4, R0.ry+r*1.85, R0.rx+i*r*.4-r*.34, R0.ry+r*2.3); }
  }
}

// ---- rolling loads ----------------------------------------------------------
for (let li=0; li<nLoad; li++){
  const L = S.lp[li]; if (L.p < -.06 || L.p > 1.06) continue;
  const lx = cxs - SPAN/2 + L.p*SPAN;
  const T = planes[0]; let ly = cys - HGT;
  if (T){ let best=1e9; for (const ti of T.top){ const n=T.N[ti]; const d2=Math.abs(n.rx-lx); if (d2<best){ best=d2; ly=ny(n,0); } } }
  const ah = u*.055*cl(P.scale,.5,1.5);
  sc(C.plot, 92); strokeWeight(Math.max(1,u*.0028*(.6+.7*NRG)));
  line(lx, ly-ah, lx, ly-ah*.16);
  line(lx, ly-ah*.16, lx-ah*.10, ly-ah*.32); line(lx, ly-ah*.16, lx+ah*.10, ly-ah*.32);
  if (anno>.3){ noStroke(); textFont('monospace'); textAlign(CENTER,BOTTOM); textSize(Math.max(6,u*.0115));
    fc(C.plot, 88); text('P'+(li+1)+' '+(24+li*17+Math.round(NRG*40))+'kN', lx, ly-ah*1.06); }
}
blendMode(BLEND);

// ---- deflection diagram -----------------------------------------------------
const T0 = planes[0];
if (T0 && anno > .1){
  const py0 = Math.min(height - u*.10, cys + HGT*.6 + u*.16);
  const amp = u*.055*(.5+.9*NRG);
  let mx2 = 1e-5;
  for (const bi of T0.bot){ const n = T0.N[bi]; const d2 = Math.abs(n.y-n.ry); if (d2>mx2) mx2 = d2; }
  S.dmax = Math.max(1e-5, Math.max((S.dmax||1e-5)*.995, mx2));
  sc(C.ctr, 54); strokeWeight(Math.max(.5,u*.0010));
  line(cxs-SPAN/2, py0, cxs+SPAN/2, py0);
  noFill(); sc(C.plot, 84); strokeWeight(Math.max(.9,u*.0022*(.6+.7*NRG)));
  beginShape();
  for (const bi of T0.bot){ const n = T0.N[bi]; vertex(n.rx, py0 + (n.y-n.ry)/S.dmax*amp); }
  endShape();
  noStroke(); fc(C.plot, 16);
  beginShape(); vertex(cxs-SPAN/2, py0);
  for (const bi of T0.bot){ const n = T0.N[bi]; vertex(n.rx, py0 + (n.y-n.ry)/S.dmax*amp); }
  vertex(cxs+SPAN/2, py0); endShape(CLOSE);
  sc(C.plot, 46); strokeWeight(Math.max(.4,u*.0007));
  for (const bi of T0.bot){ const n = T0.N[bi]; line(n.rx, py0, n.rx, py0 + (n.y-n.ry)/S.dmax*amp); }
  noStroke(); textFont('monospace'); textAlign(LEFT,CENTER); textSize(Math.max(6,u*.0125));
  fc(C.anno, 76); text('DEFLECTION x'+EX.toFixed(0)+'   dmax '+(S.dmax*1e3/u*24).toFixed(1)+' mm', cxs-SPAN/2, py0+amp*1.5+u*.022);
}

// ---- span dimension line ----------------------------------------------------
if (T0 && anno > .25){
  const dy2 = cys + u*.075*cl(P.scale,.5,1.6);
  sc(C.ctr, 70); strokeWeight(Math.max(.5,u*.0010));
  line(cxs-SPAN/2, cys+u*.03, cxs-SPAN/2, dy2+u*.012);
  line(cxs+SPAN/2, cys+u*.03, cxs+SPAN/2, dy2+u*.012);
  line(cxs-SPAN/2, dy2, cxs+SPAN/2, dy2);
  const ar = u*.012;
  line(cxs-SPAN/2, dy2, cxs-SPAN/2+ar, dy2-ar*.4); line(cxs-SPAN/2, dy2, cxs-SPAN/2+ar, dy2+ar*.4);
  line(cxs+SPAN/2, dy2, cxs+SPAN/2-ar, dy2-ar*.4); line(cxs+SPAN/2, dy2, cxs+SPAN/2-ar, dy2+ar*.4);
  noStroke(); textFont('monospace'); textAlign(CENTER,BOTTOM); textSize(Math.max(6,u*.0125));
  fc(C.anno, 88); text((nb*4).toFixed(2)+' m  ('+nb+' BAYS)', cxs, dy2-u*.006);
  // a few live member-force callouts
  textAlign(LEFT,CENTER); textSize(Math.max(5,u*.0105));
  const M0 = T0.M; const stepM = Math.max(1, Math.floor(M0.length/6));
  for (let mi=0; mi<M0.length; mi+=stepM){
    const m = M0[mi], a=T0.N[m.a], b=T0.N[m.b];
    const kN = m.f/(S.fmax+1e-9)*180;
    fc(m.f>0?C.ten:C.com, 60+30*anno);
    text((kN>0?'+':'')+kN.toFixed(0), (nx(a,0)+nx(b,0))/2 + u*.008, (ny(a,0)+ny(b,0))/2 - u*.010);
  }
}

// ---- sheet border + title block + force legend ------------------------------
const mgn = u*.028;
noFill(); sc(C.anno, 46+24*anno); strokeWeight(Math.max(.8,u*.0022));
rect(mgn, mgn, width-mgn*2, height-mgn*2);
sc(C.anno, 22+16*anno); strokeWeight(Math.max(.5,u*.0009));
rect(mgn*1.7, mgn*1.7, width-mgn*3.4, height-mgn*3.4);
if (anno > .08){
  textFont('monospace'); noStroke();
  const ts = Math.max(7,u*.0135); textSize(ts);
  textAlign(RIGHT,CENTER);
